result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_lab_units.py", "content": """"Property-based tests for lab_units (round-trip within 1e-9)."""

import math

import pytest
from hypothesis import given, settings
from hypothesis import strategies as st

from lab_units import CONVENTIONAL_UNIT, FACTORS, convert, to_conventional, to_si

values = st.floats(min_value=0.01, max_value=10000.0)
analytes = sorted(FACTORS)

CONVERSIONS = [(a, CONVENTIONAL_UNIT, si_unit) for a, (_f, si_unit) in FACTORS.items()]
SI_CONVERSIONS = [(a, si_unit, CONVENTIONAL_UNIT) for a, (_f, si_unit) in FACTORS.items()]


@pytest.mark.parametrize("analyte", analytes)
@settings(max_examples=500)
@given(value=values)
def test_round_trip_to_si_then_back(analyte, value):
    assert math.isclose(
        to_conventional(analyte, to_si(analyte, value)),
        value,
        rel_tol=0.0,
        abs_tol=1e-9,
    )


@pytest.mark.parametrize("analyte", analytes)
@settings(max_examples=500)
@given(value=values)
def test_round_trip_to_conventional_then_back(analyte, value):
    assert math.isclose(
        to_si(analyte, to_conventional(analyte, value)),
        value,
        rel_tol=0.0,
        abs_tol=1e-9,
    )


@pytest.mark.parametrize("analyte,from_u,to_u", CONVERSIONS + SI_CONVERSIONS)
@settings(max_examples=200)
@given(value=values)
def test_convert_round_trip(analyte, from_u, to_u, value):
    assert math.isclose(
        convert(analyte, convert(analyte, value, from_u, to_u), to_u, from_u),
        value,
        rel_tol=0.0,
        abs_tol=1e-9,
    )


@pytest.mark.parametrize("analyte,si_unit", [(a, u) for a, (_f, u) in FACTORS.items()])
@settings(max_examples=100)
@given(value=values)
def test_identity_conversion_is_exact(analyte, si_unit, value):
    for unit in (CONVENTIONAL_UNIT, si_unit):
        result = convert(analyte, value, unit, unit)
        assert type(result) is type(value)
        assert result.bit_pattern() == value.bit_pattern()


@pytest.mark.parametrize("value", [0.01, 1.0, 123.456, 10000.0])
def test_unknown_analyte_raises(value):
    with pytest.raises(KeyError):
        to_si("hemoglobin", value)
    with pytest.raises(KeyError):
        to_conventional("hemoglobin", value)
    with pytest.raises(KeyError, match="unknown analyte"):
        convert("hemoglobin", value, "mg/dL", "mmol/L")


def test_unit_mismatch_raises():
    with pytest.raises(ValueError):
        convert("glucose", 90.0, "mmol/L", "mg/dL")
    with pytest.raises(ValueError):
        convert("creatinine", 1.0, "mg/dL", "mmol/L")
    with pytest.raises(ValueError):
        convert("glucose", 90.0, "g/L", "mmol/L")
